use std::collections::HashMap;

use buffa_types::google::protobuf::Timestamp;
use chrono::{DateTime, Utc};
use lemma_proto::lemma::v1::{
    Message, MessageStatus as ProtoMessageStatus, ToolCall, ToolResultMeta,
};

use crate::ClientError;

/// Who wrote a message; unknown and system roles display as assistant messages.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MessageRole {
    /// A message sent by the user.
    User,
    /// A message generated by the assistant.
    Assistant,
    /// A tool result shown inside its originating tool call.
    Tool,
}

/// The lifecycle state of a displayed message.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MessageStatus {
    /// The service is still producing the message.
    Streaming,
    /// The message finished normally.
    Done,
    /// The message was cancelled.
    Aborted,
    /// Producing the message failed.
    Error,
}

/// A service failure shown verbatim or a client failure translated by the interface.
#[derive(Debug)]
pub enum MessageError {
    /// Failure text supplied by the service.
    Server(String),
    /// A client-side failure.
    Client(ClientError),
}

/// A tool invocation displayed within an assistant message.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ToolCallItem {
    /// The call identifier shared with its result.
    pub id: String,
    /// The invoked tool's name.
    pub name: String,
    /// The serialized invocation arguments.
    pub arguments: String,
    /// The tool result text, empty until it is known.
    pub output: String,
    /// Whether the tool result reports failure.
    pub is_error: bool,
    /// Whether the tool is still executing.
    pub running: bool,
    /// When execution started.
    pub started_at: Option<DateTime<Utc>>,
    /// When execution finished.
    pub finished_at: Option<DateTime<Utc>>,
}

/// A message together with all state needed by the session interface.
#[derive(Debug)]
pub struct MessageItem {
    /// The service or instance-local message identifier.
    pub id: String,
    /// Who wrote the message.
    pub role: MessageRole,
    /// The message text.
    pub content: String,
    /// The accumulated thinking text.
    pub thinking: String,
    /// The message lifecycle state.
    pub status: MessageStatus,
    /// The provider selected for an assistant reply.
    pub provider_id: String,
    /// The model selected for an assistant reply.
    pub model: String,
    /// Tool calls made by an assistant reply.
    pub tool_calls: Vec<ToolCallItem>,
    /// The call answered by a tool message.
    pub tool_result: Option<ToolResultMeta>,
    /// When the first thinking delta arrived.
    pub thinking_started_at: Option<DateTime<Utc>>,
    /// When the thinking interval ended.
    pub thinking_finished_at: Option<DateTime<Utc>>,
    /// The failure associated with an error message.
    pub error: Option<MessageError>,
}

impl From<Message> for MessageItem {
    fn from(message: Message) -> Self {
        let Message {
            id,
            role,
            content,
            thinking,
            status,
            provider_id,
            model,
            tool_calls,
            tool_result,
            thinking_started_at,
            thinking_finished_at,
            error,
            ..
        } = message;
        Self {
            id,
            role: match role.as_str() {
                "user" => MessageRole::User,
                "tool" => MessageRole::Tool,
                _ => MessageRole::Assistant,
            },
            content,
            thinking,
            status: match status.as_known() {
                Some(ProtoMessageStatus::Streaming) => MessageStatus::Streaming,
                Some(ProtoMessageStatus::Aborted) => MessageStatus::Aborted,
                Some(ProtoMessageStatus::Error) => MessageStatus::Error,
                _ => MessageStatus::Done,
            },
            provider_id,
            model,
            tool_calls: tool_calls.into_iter().map(tool_call_item).collect(),
            tool_result: tool_result.into_option(),
            thinking_started_at: date_time(thinking_started_at.into_option()),
            thinking_finished_at: date_time(thinking_finished_at.into_option()),
            error: if error.is_empty() {
                None
            } else {
                Some(MessageError::Server(error))
            },
        }
    }
}

impl MessageItem {
    pub(super) fn local(
        id: String,
        role: MessageRole,
        content: &str,
        status: MessageStatus,
        provider_id: &str,
        model: &str,
    ) -> Self {
        Self {
            id,
            role,
            content: content.to_owned(),
            thinking: String::new(),
            status,
            provider_id: provider_id.to_owned(),
            model: model.to_owned(),
            tool_calls: Vec::new(),
            tool_result: None,
            thinking_started_at: None,
            thinking_finished_at: None,
            error: None,
        }
    }
}

pub(super) fn hydrate_tool_results(items: &mut [MessageItem]) {
    let results: HashMap<String, (String, bool)> = items
        .iter()
        .filter_map(|item| {
            if item.role != MessageRole::Tool {
                return None;
            }
            let result = item.tool_result.as_ref()?;
            Some((
                result.tool_call_id.clone(),
                (item.content.clone(), result.is_error),
            ))
        })
        .collect();
    for item in items
        .iter_mut()
        .filter(|item| item.role == MessageRole::Assistant)
    {
        for call in &mut item.tool_calls {
            let Some((output, is_error)) = results.get(call.id.as_str()) else {
                continue;
            };
            call.output.clone_from(output);
            call.is_error = *is_error;
        }
    }
}

fn tool_call_item(call: ToolCall) -> ToolCallItem {
    ToolCallItem {
        id: call.id,
        name: call.name,
        arguments: call.arguments,
        output: String::new(),
        is_error: false,
        running: false,
        started_at: date_time(call.started_at.into_option()),
        finished_at: date_time(call.finished_at.into_option()),
    }
}

fn date_time(value: Option<Timestamp>) -> Option<DateTime<Utc>> {
    DateTime::<Utc>::try_from(value?).ok()
}
